// 각 검색의 순위를 점수로: score = 1 / (k + rank)   (k=60 정도, rank 1부터)
function rrf(rankedLists, k = 60) {
  const score = {};
  for (const list of rankedLists) {
    list.forEach((docId, i) => {
      const rank = i + 1;
      score[docId] = (score[docId] || 0) + 1 / (k + rank);
    });
  }
  return Object.keys(score).sort((a, b) => score[b] - score[a]);
}
// rrf([keywordResults, vectorResults])
